// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

// id_setup contract (FormContracts.js, verified:true). Do NOT send internalEmployeeId — the pre-assigned id is used.
const REQUIRED = ['workflowId','siteDocsWorkerId','siteDocsJobCode','dssUsername','dssPassword'];
const OPTIONAL = ['internalEmployeeId','formId','siteDocsUsername','siteDocsPassword','setupNotes','bossWisCreated','siteDocsBadgeCreated'];
const JOB_CODES = ['Hourly 1', 'Hourly 2', 'Salary 1', 'Salary 2', 'Supervisor', 'Manager'];   // hard-coded <option>s in EmployeeIDSetup.html
if (!empty(inp.siteDocsJobCode) && !JOB_CODES.includes(String(inp.siteDocsJobCode))) throw new Error('EFX E_VALIDATION: siteDocsJobCode must be one of ' + JOB_CODES.join('|'));
const data = Object.assign({}, asObj(inp.extra), pick(REQUIRED.concat(OPTIONAL)));
const missing = REQUIRED.filter(k => empty(data[k]));
if (missing.length) throw new Error('EFX E_VALIDATION: id_setup missing required field(s): ' + missing.join(', '));
const unknown = Object.keys(data).filter(k => !REQUIRED.includes(k) && !OPTIONAL.includes(k));
if (unknown.length) throw new Error('EFX E_VALIDATION: id_setup unknown field(s) (not in contract): ' + unknown.join(', '));
const include = bool(inp.includeRecord, false) ? ['record'] : [];
return [{ json: Object.assign({ fn: 'n8n_submitIdSetup', args: [data, include] }, passthru) }];
